content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: #f7f9fc;
  color: #333;
  line-height: 1.5;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
}

.app-container {
  width: 100%;
  max-width: 600px;
  margin: 20px;
  background: #ffffff;
  border-radius: 16px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.08);
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.header {
  text-align: center;
}

.header h1 {
  font-size: 1.8rem;
  color: #1a365d;
  margin-bottom: 8px;
}

.header p {
  font-size: 0.95rem;
  color: #64748b;
}

.filter-bar {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: center;
}

.card-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 20px;
  margin: 10px 0;
}

.flashcard {
  background-color: transparent;
  width: 100%;
  max-width: 420px;
  height: 260px;
  perspective: 1000px;
  cursor: pointer;
}

.flashcard-inner {
  position: relative;
  width: 100%;
  height: 100%;
  text-align: center;
  transition: transform 0.6s cubic-bezier(0.4, 0.2, 0.2, 1);
  transform-style: preserve-3d;
  border-radius: 16px;
  box-shadow: 0 6px 16px rgba(0, 0, 0, 0.08);
}

.flashcard.flipped .flashcard-inner {
  transform: rotateY(180deg);
}

.flashcard-front,
.flashcard-back {
  position: absolute;
  width: 100%;
  height: 100%;
  backface-visibility: hidden;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  padding: 30px;
  border-radius: 16px;
  border: 1px solid #e2e8f0;
}

.flashcard-front {
  background-color: #ffffff;
  color: #1e293b;
}

.flashcard-back {
  background-color: #f0fdf4;
  color: #166534;
  transform: rotateY(180deg);
}

.btn {
  font-family: inherit;
  font-size: 0.95rem;
  font-weight: 600;
  padding: 10px 20px;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: all 0.2s ease;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
}

.btn:active {
  transform: scale(0.98);
}

.btn-primary {
  background-color: #3b82f6;
  color: #ffffff;
}

.btn-primary:hover {
  background-color: #2563eb;
}

.btn-success {
  background-color: #22c55e;
  color: #ffffff;
}

.btn-success:hover {
  background-color: #16a34a;
}

.btn-danger {
  background-color: #ef4444;
  color: #ffffff;
}

.btn-danger:hover {
  background-color: #dc2626;
}

.stats-bar {
  display: flex;
  flex-direction: column;
  gap: 8px;
  background-color: #f8fafc;
  padding: 16px;
  border-radius: 12px;
  border: 1px solid #e2e8f0;
}

.nav-buttons {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  width: 100%;
  max-width: 420px;
  margin: 0 auto;
}

@media (max-width: 480px) {
  .app-container {
    margin: 10px;
    padding: 16px;
  }

  .flashcard {
    height: 220px;
  }
}

export interface Word {
  id: string;
  english: string;
  meaning: string;
  example: string;
  category: string;
  isMemorized: boolean;
}

import { Word } from '../types';
import '../index.css';

interface WordCardProps {
  word: Word;
  isFlipped: boolean;
  onFlip: () => void;
}

export default function WordCard({ word, isFlipped, onFlip }: WordCardProps) {
  return (
    <div 
      className={`flashcard ${isFlipped ? 'flipped' : ''}`} 
      onClick={onFlip}
    >
      <div className="flashcard-inner">
        <div className="flashcard-front">
          <span style={{ fontSize: '0.85rem', color: '#64748b', marginBottom: '8px' }}>[{word.category}]</span>
          <h2 style={{ fontSize: '2rem', fontWeight: 'bold', marginBottom: '8px' }}>{word.english}</h2>
          <span style={{ fontSize: '0.85rem', color: '#94a3b8' }}>クリックして意味を確認</span>
        </div>
        <div className="flashcard-back">
          <span style={{ fontSize: '0.85rem', color: '#15803d', marginBottom: '6px' }}>意味</span>
          <h3 style={{ fontSize: '1.5rem', fontWeight: 'bold', marginBottom: '12px' }}>{word.meaning}</h3>
          <span style={{ fontSize: '0.85rem', color: '#15803d', marginBottom: '4px' }}>例文</span>
          <p style={{ fontSize: '0.95rem', fontStyle: 'italic' }}>{word.example}</p>
        </div>
      </div>
    </div>
  );
}

import { Word } from '../types';
import '../index.css';

interface ProgressStatsProps {
  words: Word[];
}

export default function ProgressStats({ words = [] }: ProgressStatsProps) {
  const total = words.length;
  const memorized = words.filter(w => w.isMemorized).length;
  const percentage = total > 0 ? Math.round((memorized / total) * 100) : 0;

  return (
    <div className="stats-bar">
      <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.9rem', fontWeight: '600', color: '#475569' }}>
        <span>学習進捗</span>
        <span>{memorized} / {total} 覚えた ({percentage}%)</span>
      </div>
      <div style={{ width: '100%', height: '8px', backgroundColor: '#e2e8f0', borderRadius: '4px', overflow: 'hidden' }}>
        <div 
          style={{ width: `${percentage}%`, height: '100%', backgroundColor: '#22c55e', transition: 'width 0.3s ease' }} 
        />
      </div>
    </div>
  );
}

import { useState } from 'react';
import { Word } from './types';
import WordCard from './components/WordCard';
import ProgressStats from './components/ProgressStats';
import './index.css';

const initialWords: Word[] = [
  { id: '1', english: 'apple', meaning: 'りんご', example: 'I ate a red apple.', category: '果物', isMemorized: false },
  { id: '2', english: 'computer', meaning: 'コンピューター', example: 'She works on her computer.', category: 'テクノロジー', isMemorized: false },
  { id: '3', english: 'beautiful', meaning: '美しい', example: 'It is a beautiful day.', category: '形容詞', isMemorized: false },
  { id: '4', english: 'run', meaning: '走る', example: 'He likes to run in the park.', category: '動詞', isMemorized: false },
  { id: '5', english: 'book', meaning: '本', example: 'I am reading an interesting book.', category: '日用品', isMemorized: false },
  { id: '6', english: 'ocean', meaning: '海、海洋', example: 'The ocean is very deep.', category: '自然', isMemorized: false },
  { id: '7', english: 'fast', meaning: '速い', example: 'Cheetahs can run very fast.', category: '形容詞', isMemorized: false },
  { id: '8', english: 'learn', meaning: '学ぶ', example: 'We learn English every day.', category: '動詞', isMemorized: false },
  { id: '9', english: 'coffee', meaning: 'コーヒー', example: 'I drink coffee in the morning.', category: '飲み物', isMemorized: false },
  { id: '10', english: 'happy', meaning: '嬉しい、幸せな', example: 'I am happy to see you.', category: '形容詞', isMemorized: false },
];

export default function App() {
  const [words, setWords] = useState<Word[]>(initialWords);
  const [selectedCategory, setSelectedCategory] = useState<string>('すべて');
  const [currentIndex, setCurrentIndex] = useState<number>(0);
  const [isFlipped, setIsFlipped] = useState<boolean>(false);

  const categories = ['すべて', ...Array.from(new Set(initialWords.map(w => w.category)))];

  const filteredWords = selectedCategory === 'すべて' 
    ? words 
    : words.filter(w => w.category === selectedCategory);

  const currentWord = filteredWords[currentIndex] || filteredWords[0];

  const handleFlip = () => {
    setIsFlipped(!isFlipped);
  };

  const handleNext = () => {
    setIsFlipped(false);
    if (currentIndex < filteredWords.length - 1) {
      setCurrentIndex(currentIndex + 1);
    } else {
      setCurrentIndex(0);
    }
  };

  const handlePrev = () => {
    setIsFlipped(false);
    if (currentIndex > 0) {
      setCurrentIndex(currentIndex - 1);
    } else {
      setCurrentIndex(filteredWords.length - 1);
    }
  };

  const handleToggleMemorized = (isMemorized: boolean) => {
    if (!currentWord) return;
    setWords(prev => prev.map(w => w.id === currentWord.id ? { ...w, isMemorized } : w));
    handleNext();
  };

  const handleCategoryChange = (category: string) => {
    setSelectedCategory(category);
    setCurrentIndex(0);
    setIsFlipped(false);
  };

  return (
    <div className="app-container">
      <div className="header">
        <h1>英単語暗記カード</h1>
        <p>カードをクリックして意味を確認し、覚えたかどうかを記録しましょう</p>
      </div>

      <ProgressStats words={words} />

      <div className="filter-bar">
        {categories.map(cat => (
          <button
            key={cat}
            className={`btn ${selectedCategory === cat ? 'btn-primary' : ''}`}
            style={{ 
              backgroundColor: selectedCategory === cat ? '#3b82f6' : '#e2e8f0', 
              color: selectedCategory === cat ? '#ffffff' : '#334155',
              padding: '6px 14px',
              fontSize: '0.85rem'
            }}
            onClick={() => handleCategoryChange(cat)}
          >
            {cat}
          </button>
        ))}
      </div>

      {filteredWords.length > 0 ? (
        <div className="card-container">
          <div style={{ fontSize: '0.85rem', color: '#64748b' }}>
            カード {currentIndex + 1} / {filteredWords.length}
          </div>

          <WordCard 
            word={currentWord} 
            isFlipped={isFlipped} 
            onFlip={handleFlip} 
          />

          <div style={{ display: 'flex', gap: '12px', width: '100%', maxWidth: '420px', justifyContent: 'center' }}>
            <button 
              className="btn btn-danger" 
              style={{ flex: 1 }} 
              onClick={() => handleToggleMemorized(false)}
            >
              まだ
            </button>
            <button 
              className="btn btn-success" 
              style={{ flex: 1 }} 
              onClick={() => handleToggleMemorized(true)}
            >
              覚えた！
            </button>
          </div>

          <div className="nav-buttons">
            <button className="btn" style={{ backgroundColor: '#e2e8f0', color: '#334155', flex: 1 }} onClick={handlePrev}>
              前のカード
            </button>
            <button className="btn" style={{ backgroundColor: '#e2e8f0', color: '#334155', flex: 1 }} onClick={handleNext}>
              次のカード
            </button>
          </div>
        </div>
      ) : (
        <div style={{ textAlign: 'center', padding: '40px', color: '#64748b' }}>
          該当する単語がありません
        </div>
      )}
    </div>
  );
}
